results.js:
morse.watch('div[aria-label="Formatting"]', bar => {
  if (bar.querySelector('.dt-btn')) return;
  const btn = morse.el('button', {
    class: 'dt-btn',
    title: "Insert today's date",
    text: '📅',
    on: {
      click: () => {
        const d = new Date();
        const text = d.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
        const editor = document.querySelector('div[role="textbox"]');
        if (!editor) return morse.toast('No editor found');
        editor.focus();
        const sel = window.getSelection();
        if (sel && sel.rangeCount && editor.contains(sel.anchorNode)) {
          const range = sel.getRangeAt(0);
          range.deleteContents();
          range.insertNode(document.createTextNode(text));
          range.collapse(false);
        } else {
          editor.appendChild(document.createTextNode(text));
        }
        editor.dispatchEvent(new Event('input', { bubbles: true }));
      }
    }
  });
  bar.appendChild(btn);
});

morse.watch('div[role="textbox"]', ed => {
  const badge = morse.el('div', { class: 'mo-wc' });
  ed.parentNode.insertBefore(badge, ed.nextSibling);
  const update = () => {
    const t = ed.innerText.trim();
    const n = t ? t.split(/\s+/).length : 0;
    badge.textContent = n + (n === 1 ? ' word' : ' words');
  };
  update();
  new MutationObserver(update).observe(ed, { childList: true, subtree: true, characterData: true });
  morse.on(ed, 'input', update);
});

