morse.watch("header[role='banner'] > .h7r", function (bar) {
  if (bar.querySelector("[data-copy-md]")) return;
  var share = bar.querySelector("button");
  var btn = share ? share.cloneNode(false) : morse.el("button");
  btn.textContent = "Copy as Markdown";
  btn.setAttribute("data-copy-md", "");
  btn.addEventListener("click", function () {
    var md = morse.$$("section[aria-label='Conversation'] .msg[data-role]")
      .map(function (m) {
        var who = m.dataset.role === "user" ? "You" : "Assistant";
        return "**" + who + ":**\n\n" + m.innerText.trim();
      })
      .join("\n\n---\n\n");
    if (!md) { morse.toast("No messages to copy"); return; }
    navigator.clipboard.writeText(md)
      .then(function () { morse.toast("Conversation copied as Markdown"); })
      .catch(function () { morse.toast("Copy failed"); });
  });
  if (share) share.after(btn); else bar.prepend(btn);
});

