function ask(btn) {
  const name = btn.closest("article.card")?.querySelector("label")?.textContent.trim() || "this task";
  const overlay = morse.el("div", {
    style: "position:fixed;inset:0;background:rgba(0,0,0,.35);display:flex;align-items:center;justify-content:center;z-index:99999;font-family:inherit"
  },
    morse.el("div", {
      style: "background:#fff;color:inherit;border-radius:10px;padding:16px 18px;width:300px;box-shadow:0 10px 30px rgba(0,0,0,.2)"
    },
      morse.el("div", { style: "font-weight:600;margin-bottom:6px", text: "Delete task?" }),
      morse.el("div", { style: "font-size:14px;opacity:.7;margin-bottom:14px", text: "\u201C" + name + "\u201D will be deleted." }),
      morse.el("div", { style: "display:flex;gap:8px;justify-content:flex-end" },
        morse.el("button", {
          text: "Cancel",
          style: "padding:6px 12px;border:1px solid #e4e4e7;border-radius:6px;background:#fff;color:inherit;cursor:pointer",
          on: { click: () => overlay.remove() }
        }),
        morse.el("button", {
          text: "Delete",
          style: "padding:6px 12px;border:0;border-radius:6px;background:#dc2626;color:#fff;cursor:pointer",
          on: {
            click: () => {
              overlay.remove();
              btn.dataset.ok = "1";
              btn.click();
              delete btn.dataset.ok;
            }
          }
        })
      )
    )
  );
  document.body.append(overlay);
}

