morse.watch('div[data-testid="player-controls"]', el => {
  const out = morse.el('span', { class: 'sleep-timer', text: 'Off' });
  let left = 0, id = null;
  const tick = () => {
    left -= 1;
    if (left <= 0) { clearInterval(id); id = null; left = 0; out.textContent = 'Off'; morse.toast('Sleep timer ended'); const pause = document.querySelector('button[data-testid="play-pause"]'); if (pause && pause.getAttribute('aria-label') === 'Pause') pause.click(); return; }
    out.textContent = Math.ceil(left / 60) + 'm';
  };
  const btn = morse.el('button', {
    class: 'sleep-timer-btn',
    text: '⏾',
    'aria-label': 'Sleep timer',
    on: { click: () => {
      const steps = [0, 15, 30, 60];
      const cur = steps.indexOf(Math.round(left / 60));
      const next = steps[(cur + 1) % steps.length];
      clearInterval(id); id = null; left = next * 60;
      if (next) id = setInterval(tick, 1000);
      out.textContent = next ? next + 'm' : 'Off';
    } }
  });
  el.appendChild(morse.el('div', { style: 'display:flex;align-items:center;gap:6px;' }, btn, out));
});

morse.on(document, "keydown", e => {
  if (e.code !== "Space" || e.repeat) return;
  const t = e.target;
  if (t.closest && t.closest("input, textarea, select, [contenteditable='true']")) return;
  if (t.closest && t.closest("button, a[href]")) e.preventDefault();
  const btn = document.querySelector('button[data-testid="play-pause"]');
  if (!btn) return;
  e.preventDefault();
  btn.click();
});

