morse.watch('div[aria-label="Log\\ lines"] > div.sz > div.row', row => {
  if (row.querySelector(':scope > .cp')) return;
  const btn = morse.el('button', {
    class: 'cp',
    type: 'button',
    title: 'Copy line',
    text: 'Copy',
    on: {
      click: e => {
        e.stopPropagation();
        const t = s => (row.querySelector(s) || {}).textContent || '';
        const line = [t('.ts'), t('.lv'), t('.svc'), t('.msg')].join(' ');
        const done = () => {
          btn.textContent = 'Copied';
          setTimeout(() => { btn.textContent = 'Copy'; }, 1000);
        };
