          navigator.clipboard.writeText(line).then(done, () => {});
        } else {
          const ta = morse.el('textarea', { style: 'position:fixed;opacity:0' });
          ta.value = line;
          document.body.appendChild(ta);
          ta.select();
          document.execCommand('copy');
          ta.remove();
          done();
        }
      }
    }
  });
  row.appendChild(btn);
}, { live: true });

